import base64
from pathlib import Path

OUT=Path('pkgfiles/USRDIR')
OUT.mkdir(parents=True,exist_ok=True)

TOP=''''''
LEFT=''''''
RIGHT=''''''
BOTTOM=''''''
BOTTOM=''''''

files={'CASE_TOP.JPG':TOP,'CASE_LEFT.PNG':LEFT,'CASE_RIGHT.PNG':RIGHT,'CASE_BOTTOM.PNG':BOTTOM}
